solution.solution.cpp:
#include <string>
#include <string_view>

std::string describe(int value)
{
    return "int: " + std::to_string(value);
}

std::string describe(double value)
{
    return "double: " + std::to_string(value);
}

std::string describe(bool value)
{
    return value ? "bool: true" : "bool: false";
}

std::string describe(std::string_view value)
{
    return "text: " + std::string{ value };
}

unitTests:
TEST("int") { CHECK_EQ(describe(42), "int: 42"); CHECK_EQ(describe(-7), "int: -7"); }
TEST("double") { CHECK_EQ(describe(2.5), "double: 2.500000"); }
TEST("bool") { CHECK_EQ(describe(true), "bool: true"); CHECK_EQ(describe(false), "bool: false"); }
TEST("text") { CHECK_EQ(describe(std::string_view{ "hi" }), "text: hi"); }

